style.css:
@-moz-document domain("forum.rodina-rp.com") {
/* Устанавливаем картинку на фон */
    body {
        background-image: url('https://i.pinimg.com/1200x/76/45/eb/7645ebb8fc1ba2d4168e25bf2ac0b0a1.jpg') !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* Делаем контентную часть полупрозрачной */
    .p-pageWrapper, .p-body, .p-sectionLinks, .p-header, .p-navSticky {
        background: rgba(0, 0, 0, 0.7) !important; /* Черный цвет с 70% непрозрачности */
        backdrop-filter: blur(8px); /* Легкое размытие фона за блоками */
    }

    /* Прозрачность для блоков с сообщениями */
    .block-container {
        background: rgba(25, 25, 25, 0.5) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
    }
}
